);


--
-- Name: User; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."User" (
    id text NOT NULL,
    email text NOT NULL,
    "regNo" text,
    "fullName" text NOT NULL,
    "passwordHash" text NOT NULL,
    "mustChangePassword" boolean DEFAULT false NOT NULL,
    role public."RoleType" NOT NULL,
    "organizationId" text,
    "teamId" text,
    year text,
    department text,
    "deptCode" text,
    cluster text,
    gender text,
    resident text,
    "learningMode" text,
    "ssgEnrolled" boolean DEFAULT false NOT NULL,
    "ssgDomain" text,
    "groupRegistered" boolean DEFAULT false NOT NULL,
    "skillsRegistered" boolean DEFAULT false NOT NULL,
    "rewardPoints" integer DEFAULT 0 NOT NULL,
    "activityPoints" integer DEFAULT 0 NOT NULL,
    "teamRole" text,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    "githubUsername" text
);


--
-- Name: UserAIProvider; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."UserAIProvider" (
    id text NOT NULL,
    "userId" text NOT NULL,
